bug_report:
[12 Regression] Does not fully checking for overlapping memory regions with the vectorizer
This test case is used to check whether the value stored in the memory is correct when the memory overlaps.

compile option: -march=rv64gcv_zvl128b -mabi=lp64d -fno-inline -O3

testcase:

#include <stdlib.h>
#include <string.h>

struct st
{
  unsigned int num : 8;
};

void mem_overlap (struct st *a, struct st *b) {
  for (int i = 0; i < 9; i++) {
    a[i].num = b[i].num + 1;
  }
}

int main (void) {
  struct st * a;
  a = (struct st*) malloc (9 * sizeof(struct st));
  memset (a, 0, 9 * sizeof(struct st));

  // input a = 0, 0, 0, 0, 0, 0, 0, 0, 0
  mem_overlap(&a[1], a);

  // output a = 0, 1, 2, 3, 4, 5, 6, 7, 8
  if (a[2].num == 2)
    exit(0);
  else
    abort();
}

